class Solution {
public:
    int flipgame(vector<int>& fronts, vector<int>& backs) {
        unordered_set<int> forbidden;
        for (int i = 0; i < (int)fronts.size(); ++i)
            if (fronts[i] == backs[i]) forbidden.insert(fronts[i]);
        int best = INT_MAX;
        for (int x : fronts) if (!forbidden.count(x)) best = min(best, x);
        for (int x : backs) if (!forbidden.count(x)) best = min(best, x);
        return best == INT_MAX ? 0 : best;
    }
};
